SourceCode.Declaration:
/// <summary>
/// Each handheld's item sync as it last reported it (HSMobileOpsSkuPageSvc/reportSync): sent by
/// the app at the end of every item sync, finished or failed. Mobile sync health reads it to show
/// which devices are up to date, which are failing and which have gone quiet.
///
/// One row per device and company. A device that cannot reach D365FO cannot report; it shows up
/// as stale once its last successful sync is older than staleHours().
/// </summary>
public class HSMobileOpsDeviceSync extends common
{
}

Method.Source:
/// <summary>
/// A device whose last successful item sync is older than this is stale. The item sync runs
/// once a day, on Wi-Fi while charging, so two days allows for a missed night.
/// </summary>
public static int staleHours()
{
    return 48;
}

/// <summary>Records one device's report; the caller has checked the company and the device id.</summary>
public static void report(HSMobileOpsSkuSyncReport _report)
{
    HSMobileOpsDeviceSync row;
    utcdatetime           now = DateTimeUtil::utcNow();

    ttsbegin;
    select forUpdate firstOnly row
        where row.DeviceId == _report.parmDeviceId();
    row.DeviceId      = _report.parmDeviceId();
    row.Warehouse     = _report.parmWarehouse();
    row.Scope         = _report.parmScope();
    row.AppVersion    = subStr(_report.parmAppVersion(), 1, 32);
    row.LastReportUtc = now;
    if (_report.parmSucceeded())
    {
        row.LastSuccessUtc = now;
        row.LastFull       = _report.parmFull() ? NoYes::Yes : NoYes::No;
        row.Items          = _report.parmItems();
        row.Barcodes       = _report.parmBarcodes();
        row.SyncSeconds    = _report.parmSeconds();
    }
    else
    {
        row.LastErrorUtc = now;
        row.LastError    = subStr(_report.parmMessage(), 1, 250);
    }
    if (row.RecId)
    {
        row.update();
    }
    else
    {
        row.insert();
    }
    ttscommit;
}

/// <summary>Its last sync failed (an error after the last success).</summary>
public boolean isFailing()
{
    return this.LastErrorUtc && this.LastErrorUtc > this.LastSuccessUtc;
}

/// <summary>No successful item sync for staleHours().</summary>
public boolean isStale()
{
    return !this.LastSuccessUtc
        || DateTimeUtil::getDifference(DateTimeUtil::utcNow(), this.LastSuccessUtc) > HSMobileOpsDeviceSync::staleHours() * 3600;
}

/// <summary>What an administrator needs first: OK, failing (with why) or stale (since when).</summary>
public display str health()
{
    str  text;
    int64 hours;

    if (this.isFailing())
    {
        text = 'Failing: ' + this.LastError;
    }
    else if (!this.LastSuccessUtc)
    {
        text = 'Never finished a sync';
    }
    else if (this.isStale())
    {
        hours = DateTimeUtil::getDifference(DateTimeUtil::utcNow(), this.LastSuccessUtc) div 3600;
        text  = hours >= 48 ? strFmt('Stale: last sync %1 days ago', hours div 24) : strFmt('Stale: last sync %1 hours ago', hours);
    }
    else
    {
        text = 'OK';
    }
    return text;
}

public display Name deviceName()
{
    HSMobileOpsDevice device;

    select firstOnly FriendlyName from device where device.DeviceId == this.DeviceId;
    return device.FriendlyName;
}

public display HSMobileOpsUserName lastUser()
{
    HSMobileOpsDevice device;

    select firstOnly LastUserName from device where device.DeviceId == this.DeviceId;
    return device.LastUserName;
}

/// <summary>Which items the device holds: every item, or the store's assortment.</summary>
public display str itemsOf()
{
    return this.Scope ? 'Store assortment' : 'All items';
}
